    res.exitCode,
    '${res.stdout}${res.stderr}',
    File(outPath).existsSync() ? _parseOutputs(outPath) : {},
    File('${dir.path}/gh.log').existsSync()
        ? File('${dir.path}/gh.log').readAsLinesSync()
        : <String>[],
  );
}

